{"t_ms":720,"direction":"in","line":"{\"result\":{\"tools\":[{\"name\":\"game_state\",\"title\":\"Read game state\",\"description\":\"Read the live Fruit Ninja Dojo state: phase (menu/playing/result), mode, score, misses, seconds remaining, the airborne fruits and bombs with positions and velocities in arena coordinates, and the start button position. Read-only; sends no input.\",\"inputSchema\":{\"$schema\":\"http://json-schema.org/draft-07/schema#\",\"type\":\"object\",\"properties\":{}},\"execution\":{\"taskSupport\":\"forbidden\"}},{\"name\":\"start_round\",\"title\":\"Start the round\",\"description\":\"Click the start button with a native mouse click to begin the prepared round. Only a native click can start the round. Returns the resulting game state.\",\"inputSchema\":{\"$schema\":\"http://json-schema.org/draft-07/schema#\",\"type\":\"object\",\"properties\":{}},\"execution\":{\"taskSupport\":\"forbidden\"}},{\"name\":\"slice\",\"title\":\"Slice a stroke through the fruit\",\"description\":\"Perform one blade stroke: the server observes the arena, plans a single native mouse path that sweeps through as many fruits as possible while keeping clear of bombs, and executes it. If no fruit is airborne it waits briefly for the next wave. Returns the score gained and the new state. If the round has not been started yet, this call presses the start button instead and reports reason \\\"round-started\\\".\",\"inputSchema\":{\"$schema\":\"http://json-schema.org/draft-07/schema#\",\"type\":\"object\",\"properties\":{\"max_duration_ms\":{\"description\":\"Upper bound on the stroke duration in milliseconds (default 900).\",\"type\":\"integer\",\"minimum\":20,\"maximum\":1000},\"speed\":{\"description\":\"Blade speed in arena px/s used while planning (default 3200).\",\"type\":\"number\",\"minimum\":600,\"maximum\":4800},\"bomb_margin\":{\"description\":\"Extra clearance in px kept from bomb centres (default 26).\",\"type\":\"number\",\"minimum\":0,\"maximum\":200},\"wait_ms\":{\"description\":\"How long to wait for fruit to appear before giving up (default 2500).\",\"type\":\"integer\",\"minimum\":0,\"maximum\":5000}}},\"execution\":{\"taskSupport\":\"forbidden\"}},{\"name\":\"slice_fruit\",\"title\":\"Slice one specific fruit\",\"description\":\"Perform one blade stroke aimed at a single fruit id reported by game_state, then continue through any other fruit that lies along the way. Use this when you want precise control (for example to pick off a fruit near a bomb).\",\"inputSchema\":{\"$schema\":\"http://json-schema.org/draft-07/schema#\",\"type\":\"object\",\"properties\":{\"fruit_id\":{\"type\":\"integer\",\"minimum\":-9007199254740991,\"maximum\":9007199254740991,\"description\":\"The id of the fruit to slice, from game_state.\"},\"max_duration_ms\":{\"type\":\"integer\",\"minimum\":20,\"maximum\":1000},\"speed\":{\"type\":\"number\",\"minimum\":600,\"maximum\":4800},\"bomb_margin\":{\"type\":\"number\",\"minimum\":0,\"maximum\":200}},\"required\":[\"fruit_id\"]},\"execution\":{\"taskSupport\":\"forbidden\"}}]},\"jsonrpc\":\"2.0\",\"id\":1}"}
